/* Offline-first. IndexedDB is the authoritative on-device event store. */
const DB='box-lacrosse-v2', STORE='state';let db, state, pendingEntry=null, syncing=false;
const $=id=>document.getElementById(id), uuid=()=>crypto.randomUUID(), escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB,1);req.onupgradeneeded=()=>req.result.createObjectStore(STORE);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function readState(){return new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).get('app');r.onsuccess=()=>resolve(r.result||{games:[],activeId:null,syncUrl:'',syncKey:''});r.onerror=()=>reject(r.error)})}
function persist(){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(state,'app');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
const active=()=>state.games.find(g=>g.id===state.activeId);
function initRosters(){if(!state.rosters)state.rosters={};for(const team of LEAGUE_DATA.teams){if(!state.rosters[team.id])state.rosters[team.id]=team.roster.map(r=>({...r,teamId:team.id,dirty:false}));}}
function teamId(g,t){const name=(t?g.away:g.home).name;return LEAGUE_DATA.teams.find(x=>x.name.toLowerCase()===name.toLowerCase())?.id||name.toLowerCase().replace(/\s+/g,'-')}
function roster(g,t){const id=teamId(g,t);return g.rosterSnapshot?.[id]||state.rosters[id]||[]}
function gameAttendance(g,t){g.attendance=g.attendance||{};const id=teamId(g,t);if(!g.attendance[id])g.attendance[id]=Object.fromEntries(roster(g,t).map(r=>[r.id,true]));return g.attendance[id]}
function findPlayer(g,t,jersey){return roster(g,t).find(r=>r.jersey===String(jersey))}
function playerId(g,t,jersey){return findPlayer(g,t,jersey)?.id||''}
function enrichEvent(g,e){if(e.type==='goal'){e.scorerId=playerId(g,e.team,e.scorer);e.assistId=e.assist?playerId(g,e.team,e.assist):''}if(e.type==='penalty')e.playerId=playerId(g,e.team,e.player);if(e.type==='save'||e.type==='goalie_change')e.goalieId=playerId(g,e.team,e.goalie);if(e.type==='goal')e.goalieAgainstId=playerId(g,1-e.team,e.goalieAgainst);return e}
// V19: position-independent jersey pads. The game-day dressed list is authoritative.
const V19_FIELDS={scorer:()=>pendingEntry?.team,assist:()=>pendingEntry?.team,penPlayer:()=>pendingEntry?.team,newGoalieNumber:()=>changingTeam,editScorer:()=>Number($('editTeam').value),editAssist:()=>Number($('editTeam').value),editPlayer:()=>Number($('editTeam').value),editGoalie:()=>Number($('editTeam').value),homeGoalie:()=>0,awayGoalie:()=>1};
const V19_OPTIONAL=new Set(['assist','editAssist']);
function v19Dressed(g,t){if(!g)return [];const a=gameAttendance(g,t);return roster(g,t).filter(r=>a[r.id]!==false).sort((x,y)=>Number(x.jersey)-Number(y.jersey))}
function v19Player(g,t,n){return v19Dressed(g,t).find(r=>String(r.jersey)===String(n))}
function v19Require(g,t,n,label,optional=false){if(optional&&n==='')return true;if(!v19Player(g,t,n)){alert(label+' #'+(n||'?')+' is not on the dressed roster. Open Review players to activate or add the player.');return false}return true}
function v19Pad(id,t,allowNone=false){const el=$(id);if(!el)return;let pad=document.getElementById('v19-pad-'+id);if(!pad){pad=document.createElement('div');pad.id='v19-pad-'+id;el.insertAdjacentElement('afterend',pad);el.classList.add('padManaged');el.setAttribute('aria-hidden','true');el.tabIndex=-1}const setup=['homeGoalie','awayGoalie'].includes(id);const g=active();const rs=setup?[]:(g?v19Dressed(g,t):[]);if(setup){const name=$(t?'awayName':'homeName').value.trim();const team=LEAGUE_DATA.teams.find(x=>x.name.toLowerCase()===name.toLowerCase());const list=team?state.rosters[team.id]||team.roster:[];const draft=state.pregameDrafts?.[pregameKey()];const att=draft?.attendance?.[team?.id];rs.push(...list.filter(r=>!att||att[r.id]!==false).sort((x,y)=>Number(x.jersey)-Number(y.jersey)))}pad.innerHTML=rs.length?'<div class="playerPad">'+rs.map(r=>'<button type="button" data-jersey="'+escapeHTML(r.jersey)+'" class="'+(String(el.value)===String(r.jersey)?'picked':'')+'" title="'+escapeHTML(r.name)+'">#'+escapeHTML(r.jersey)+'<small>'+escapeHTML(r.name.split(' ').at(-1))+'</small></button>').join('')+(allowNone?'<button type="button" class="none '+(!el.value?'picked':'')+'" data-jersey="">No assist</button>':'')+'</div>':'<p class="playerPadEmpty">No players available. Check the game-day roster first.</p>';pad.onclick=e=>{const b=e.target.closest('button[data-jersey]');if(!b)return;el.value=b.dataset.jersey;v19Pad(id,t,allowNone)};}
function v19EntryPads(){const g=active();if(!g||!pendingEntry)return;const t=pendingEntry.team;if(pendingEntry.type==='goal'){v19Pad('scorer',t);v19Pad('assist',t,true)}else v19Pad('penPlayer',t)}
function v19EditPads(type){const t=Number($('editTeam').value);if(type==='goal'){v19Pad('editScorer',t);v19Pad('editAssist',t,true)}else if(type==='penalty')v19Pad('editPlayer',t);else v19Pad('editGoalie',t)}
function renderRosters(){const g=active();if(!g)return;$('rosterTeams').innerHTML=[0,1].map(t=>{const att=gameAttendance(g,t),rs=roster(g,t);return `<div class="card"><h3>${escapeHTML((t?g.away:g.home).name)} · ${rs.filter(r=>att[r.id]!==false).length}/${rs.length} playing</h3>${rs.map(r=>`<label style="display:flex;align-items:center;gap:9px;padding:5px 0"><input type="checkbox" data-attteam="${t}" data-attid="${escapeHTML(r.id)}" ${att[r.id]!==false?'checked':''} ${g.status==='final'?'disabled':''} style="width:22px;min-height:22px"><span>#${escapeHTML(r.jersey)} ${escapeHTML(r.name)}${r.goalie?' · G':''}</span></label>`).join('')||'<small>No master roster yet.</small>'}</div>`}).join('');$('addPlayerTeam').options[0].textContent=g.home.name;$('addPlayerTeam').options[1].textContent=g.away.name;$('addPlayerForm').querySelector('button').disabled=g.status==='final'}

const prettyTime=t=>{if(!t)return '';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
function events(g){return g.events.filter(e=>!e.deleted)}
function totals(g,team){const ev=events(g);return {goals:ev.filter(e=>e.type==='goal'&&e.team===team).length,saves:ev.filter(e=>e.type==='save'&&e.team===team).length,penalties:ev.filter(e=>e.type==='penalty'&&e.team===team).length}}
function startingGoalie(g,t){return String((t?g.away:g.home).goalie||'')}
function currentGoalie(g,t){let n=startingGoalie(g,t);for(const e of events(g)){if(e.type==='goalie_change'&&e.team===t)n=String(e.goalie||'')}return n}
function validJersey(v,optional=false){return optional&&v===''||/^\d+$/.test(v)}
function markMeta(g,action,before,after){auditLog(g,action,before,after)}
function status(){const last=$('lastSync');if(last)last.textContent=state.lastSyncAt?'Last confirmed sync: '+new Date(state.lastSyncAt).toLocaleString():'No confirmed Google Sheets sync yet.';const count=state.games.reduce((n,g)=>n+g.events.filter(e=>e.dirty).length+(g.metaDirty?1:0),0);$('syncStatus').textContent=!navigator.onLine?`Offline · ${count} pending`:count?`${count} awaiting sync`:'Saved locally ✓';$('syncStatus').title='Local entries remain available offline'}
function show(view){['score','setup','events','summary','history','review'].forEach(n=>{$(n+'View').classList.toggle('hidden',n!==view);(($(n+'Tab'))&&$(n+'Tab').classList.toggle('secondary',n!==view))});render()}
function render(){const g=active();$('scoreView').querySelectorAll('button').forEach(b=>{if(['undoBtn','nextQ','prevQ'].includes(b.id))return});$('gameLabel').textContent=g?`${g.home.name} vs ${g.away.name}${g.scheduledStart?' · '+prettyTime(g.scheduledStart):''}`:'Create a game in Game Setup';$('quarterLabel').textContent=`Q${g?.quarter||1}`;$('quarterText').textContent=`Quarter ${g?.quarter||1}`;$('prevQ').disabled=!g||g.quarter===1;$('nextQ').disabled=!g||g.quarter===4;$('undoBtn').disabled=$('undoReviewBtn').disabled=!g||g.status==='final'||!events(g).length;$('gameStatus').textContent=g?.status==='final'?'Final':g?.status==='review'?'Pending review':'In progress';$('reviewBtn').disabled=!g;
$('teamCards').innerHTML=g?[0,1].map(t=>{const team=t?g.away:g.home,tot=totals(g,t);return `<div class="team" style="--tc:${team.color}"><b>${escapeHTML(team.name)}</b><div class="score">${tot.goals}</div><button data-action="goal" data-team="${t}" ${g.status==='final'?'disabled':''}>+ Goal</button><small>ACTIVE GOALIE #${escapeHTML(currentGoalie(g,t)||'NOT SET')}</small><button class="secondary" data-action="change_goalie" data-team="${t}" ${g.status==='final'?'disabled':''}>Change Goalie</button><small>GOALIE SAVES</small><div class="stat">${tot.saves}</div><button class="secondary" data-action="save" data-team="${t}" ${g.status==='final'?'disabled':''}>+1 Save</button><small>Penalties: ${tot.penalties}</small><button class="secondary" data-action="penalty" data-team="${t}" ${g.status==='final'?'disabled':''}>+ Penalty</button></div>`}).join(''):'<p>Set up your first game to begin.</p>';
$('quarterScores').innerHTML=[1,2,3,4].map(q=>`<div class="${g?.quarter===q?'active':''}"><small>Q${q}</small><br><b>${g?events(g).filter(e=>e.type==='goal'&&e.quarter===q&&e.team===0).length:0}–${g?events(g).filter(e=>e.type==='goal'&&e.quarter===q&&e.team===1).length:0}</b></div>`).join('');
const visibleEvents=g?events(g).filter(e=>($('eventFilter').value==='all'||e.type===$('eventFilter').value)&&($('eventTeamFilter').value==='all'||e.team===Number($('eventTeamFilter').value))):[]; $('eventCount').textContent=g?`${visibleEvents.length} matching events of ${events(g).length} saved · showing newest 40`:'No active game'; $('eventList').innerHTML=g?visibleEvents.slice().reverse().slice(0,40).map(e=>`<div class="event"><div class="between"><span>${e.type==='goal'?'🥍 Goal':e.type==='save'?'🧤 Save':e.type==='goalie_change'?'🔁 Goalie change':'🚩 Penalty'} · ${escapeHTML((e.team?g.away:g.home).name)} · Q${e.quarter}${e.remaining!==null?' · '+escapeHTML(e.remaining):''}</span><button class="secondary" data-delete="${e.id}" ${g.status==='final'?'disabled':''}>Remove</button></div><small>${e.type==='goal'?`#${escapeHTML(e.scorer)}${e.assist?' · Assist #'+escapeHTML(e.assist):' · Unassisted'} · ${e.goalType} · ${e.minute}'`:e.type==='penalty'?`#${escapeHTML(e.player)} · ${escapeHTML(e.infraction)} · ${e.duration||1} min · ${e.minute}'`:e.type==='goalie_change'?`New goalie #${escapeHTML(e.goalie)}`:`Goalie #${escapeHTML(e.goalie||'Unassigned')} save`}</small></div>`).join('')||'<small>No events yet.</small>':'<small>No active game.</small>';
if($('liveSummary'))$('liveSummary').innerHTML=g?buildLiveSummary(g):'<small>Start a game to see summaries.</small>';
if($('rosterSummary'))$('rosterSummary').textContent=g?[0,1].map(t=>{const a=gameAttendance(g,t);return (t?g.away:g.home).name+': '+roster(g,t).filter(r=>a[r.id]!==false).length+' playing'}).join(' · '):'Start a game to review rosters.';
$('gameHistory').innerHTML=state.games.slice().reverse().map(g=>`<div class="event between"><div><b>${escapeHTML(g.home.name)} ${totals(g,0).goals} – ${totals(g,1).goals} ${escapeHTML(g.away.name)}</b><br><small>${escapeHTML(g.date)}${g.scheduledStart?' · Scheduled '+prettyTime(g.scheduledStart):''}${g.actualStart?' · Actual '+prettyTime(g.actualStart):''} · ${g.status||'in progress'} · Q${g.quarter} · ${events(g).length} events</small></div><div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end"><button data-open="${g.id}">Open</button><button class="secondary" data-attendance-edit="${g.id}">Edit attendance</button><button class="secondary" data-resync="${g.id}">Resync to Google Sheets</button><button class="warn" data-delete-game="${g.id}">Delete game</button></div></div>`).join('')||'<small>No games saved.</small>';status()}
async function commit(){await persist();render();if(navigator.onLine)sync().catch(()=>{})}
function elapsedTime(){const raw=$('remainingSec').value.trim(),m=Number($('remainingMin').value),s=raw===''?0:Number(raw);if($('remainingMin').value===''||!Number.isInteger(m)||!Number.isInteger(s)||m<0||m>12||s<0||s>59||m*60+s>720)return null;const elapsed=720-(m*60+s);return {remaining:raw===''?String(m).padStart(2,'0')+':--':`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`,secondsKnown:raw!=='',elapsed,minute:Math.max(1,Math.ceil(elapsed/60))}}
function clockPreview(){const t=elapsedTime();$('clockHelp').textContent=t?`Elapsed: ${Math.floor(t.elapsed/60)}:${String(t.elapsed%60).padStart(2,'0')} · Scoring minute ${t.minute}'`:'Enter a valid time from 12:00 to 00:00'}
function openEntry(type,team){pendingEntry={type,team};$('entryTitle').textContent=`${type==='goal'?'Goal':'Penalty'} · ${(team?active().away:active().home).name}`;$('goalFields').classList.toggle('hidden',type!=='goal');$('penaltyFields').classList.toggle('hidden',type!=='penalty');$('scorer').required=type==='goal';$('penPlayer').required=type==='penalty';$('remainingMin').value='';$('remainingSec').value='';$('scorer').value='';$('assist').value='';$('penPlayer').value='';$('goalType').value='EV';$('infraction').value='Slashing';$('penDuration').value='1';clockPreview();v19EntryPads();$('entryDialog').showModal()}
let changingTeam=null;
function openGoalieChange(t){const g=active();changingTeam=t;$('goalieTitle').textContent=`Change goalie · ${(t?g.away:g.home).name} (currently #${currentGoalie(g,t)||'none'})`;$('newGoalieNumber').value='';$('goalieQuarter').value=String(g.quarter);$('goalieMin').value='';$('goalieSec').value='';$('goalieChangeMode').value='substitution';v19Pad('newGoalieNumber',t);$('goalieDialog').showModal()}
$('cancelGoalie').onclick=()=>$('goalieDialog').close();
$('goalieForm').onsubmit=async ev=>{ev.preventDefault();const g=active();if(!g||g.status==='final')return;const n=$('newGoalieNumber').value.trim(),m=$('goalieMin').value.trim(),s=$('goalieSec').value.trim();if(!validJersey(n)){alert('Enter a goalie jersey number.');return}if(!v19Require(g,changingTeam,n,'Goalie'))return;if($('goalieChangeMode').value==='opening'){if(Number($('goalieQuarter').value)!==1||events(g).some(e=>e.type!=='goalie_change'||Number(e.quarter)!==1||e.elapsed!==0)){alert('Opening correction is only available before recorded play.');return}if(!confirm('Confirm no game time has elapsed.'))return;$('goalieDialog').close();await addEvent({type:'goalie_change',team:changingTeam,goalie:n,quarter:1,remaining:'12:00',elapsed:0});return}if(m===''){alert('Enter the game time for a substitution.');return}if(m!==''&&(!Number.isInteger(Number(m))||Number(m)<0||Number(m)>12||s!==''&&(!Number.isInteger(Number(s))||Number(s)<0||Number(s)>59)||Number(m)*60+Number(s||0)>720)){alert('Enter a valid scoreboard time.');return}const remaining=m===''?null:String(m).padStart(2,'0')+':'+(s===''?'--':String(s).padStart(2,'0'));$('goalieDialog').close();await addEvent({type:'goalie_change',team:changingTeam,goalie:n,quarter:Number($('goalieQuarter').value),remaining,elapsed:m===''?null:720-(Number(m)*60+Number(s||0))})};
async function addEvent(e){const g=active();if(g.status==='final')return;enrichEvent(g,e);g.events.push({...e,id:uuid(),quarter:e.quarter||g.quarter,createdAt:new Date().toISOString(),deleted:false,dirty:true,version:1});await commit()}
// Reconcile roster additions against server-confirmed IDs, including players created in V12.
function localRosterAdditions(){const seeds=new Set(LEAGUE_DATA.teams.flatMap(t=>t.roster.map(r=>r.id)));return Object.values(state.rosters||{}).flat().filter(r=>r.id&&r.teamId&&r.dirty&&!seeds.has(r.id)&&(!state.confirmedRosterIds||!state.confirmedRosterIds.includes(r.id)))}
function mergeServerRosters(rows){
  let added=0,updated=0;
  for(const r of rows||[]){
    if(!r.id||!r.teamId||!r.name)continue;
    const rs=state.rosters[r.teamId]||(state.rosters[r.teamId]=[]);
    const existing=rs.find(x=>x.id===r.id);
    if(existing){
      // Never overwrite a locally added player that has not yet been confirmed by the server.
      if(existing.dirty && !(state.confirmedRosterIds||[]).includes(r.id))continue;
      const jersey=String(r.jersey),name=String(r.name),goalie=!!r.goalie;
      if(existing.jersey!==jersey||existing.name!==name||!!existing.goalie!==goalie){
        existing.jersey=jersey;existing.name=name;existing.goalie=goalie;updated++;
      }
      continue;
    }
    // Do not create a second local identity for a matching player.
    if(rs.some(x=>String(x.jersey)===String(r.jersey)&&String(x.name).toLowerCase()===String(r.name).toLowerCase()))continue;
    rs.push({...r,jersey:String(r.jersey),goalie:!!r.goalie,dirty:false});added++;
  }
  return {added,updated,received:Array.isArray(rows)?rows.length:0};
}
async function sync(force=false){if(syncing){if(force)$('notice').textContent='Sync already running; please wait.';return}if(!navigator.onLine){if(force)$('notice').textContent='Offline: sync will resume when connected.';return}if(!state.syncUrl||!state.syncKey){if(force)$('notice').textContent='Enter and save the Apps Script URL and sync key first.';return}syncing=true;if(force)$('notice').textContent='Contacting Google Sheets…';try{if(!state.confirmedRosterIds)state.confirmedRosterIds=[];const rosterBatch=localRosterAdditions();const games=state.games.filter(g=>g.metaDirty||g.events.some(e=>e.dirty));if(!games.length){if(force)$('notice').textContent='No game to sync. Start or open a game first.';return}for(const g of games){const batch=g.events.filter(e=>e.dirty),snapshot=batch.map(e=>({id:e.id,version:e.version||0})),gameVersion=g.version||0;const payload={key:state.syncKey,game:{id:g.id,date:g.date,home:g.home,away:g.away,quarter:g.quarter,status:g.status||'in_progress',verifiedHome:g.verifiedHome,verifiedAway:g.verifiedAway,finalizedAt:g.finalizedAt||'',audit:g.audit||[],scheduledStart:g.scheduledStart||'',actualStart:g.actualStart||'',referees:g.referees||[]},events:batch,rosterUpdates:rosterBatch,attendance:g.attendance||{},gameRosters:g.rosterSnapshot||null,includeRosters:force};const response=await fetch(state.syncUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload),redirect:'follow'});if(!response.ok)throw Error('HTTP '+response.status);const result=await response.json();if(!result.ok)throw Error(result.error||'Sync rejected');if(!Array.isArray(result.rosterConfirmed))throw Error('Apps Script is not V12.1 yet; roster confirmation missing. Update deployment first.');const confirmed=new Set(result.rosterConfirmed);for(const r of rosterBatch){if(!confirmed.has(r.id))throw Error('Player '+r.name+' was not confirmed in Rosters');if(!state.confirmedRosterIds.includes(r.id))state.confirmedRosterIds.push(r.id);const live=(state.rosters[r.teamId]||[]).find(x=>x.id===r.id);if(live)live.dirty=false}const sent=new Map(snapshot.map(e=>[e.id,e.version]));for(const e of g.events){if(sent.has(e.id)&&sent.get(e.id)===(e.version||0))e.dirty=false}if((g.version||0)===gameVersion)g.metaDirty=false;const rosterResult=mergeServerRosters(result.masterRosters);state.lastSyncAt=new Date().toISOString();await persist();if(force)$('notice').textContent='Server confirmed sync: '+rosterBatch.length+' player additions verified in Rosters; '+rosterResult.received+' master roster records received; '+rosterResult.updated+' existing players updated; '+rosterResult.added+' new players added.'}}catch(e){$('notice').textContent='Sync pending: '+e.message}finally{syncing=false;status()}}
// V18: explicitly restore one complete saved game, including previously synced events.
// This never edits the local game or its sync/dirty flags. The server upserts by game/event ID.
async function resyncSavedGame(gameId){
  const g=state.games.find(x=>x.id===gameId);
  if(!g)return;
  if(syncing){alert('Another sync is running. Please try again.');return}
  if(!navigator.onLine){alert('Connect to the internet before resyncing.');return}
  if(!state.syncUrl||!state.syncKey){alert('Save the Google Sheets URL and sync key first.');return}
  if(!confirm(`Resend the complete saved game ${g.home.name} vs ${g.away.name} (${g.date}) to Google Sheets? This restores all ${g.events.length} recorded events and attendance, including corrections. It will not change the saved game on this iPad.`))return;
  syncing=true;
  const btn=document.querySelector('button[data-resync="'+CSS.escape(gameId)+'"]');
  if(btn){btn.disabled=true;btn.textContent='Resyncing…'}
  try{
    const payload={key:state.syncKey,game:{id:g.id,date:g.date,home:g.home,away:g.away,quarter:g.quarter,status:g.status||'in_progress',verifiedHome:g.verifiedHome,verifiedAway:g.verifiedAway,finalizedAt:g.finalizedAt||'',audit:g.audit||[],scheduledStart:g.scheduledStart||'',actualStart:g.actualStart||'',referees:g.referees||[]},events:g.events,rosterUpdates:[],attendance:g.attendance||{},gameRosters:g.rosterSnapshot||null,includeRosters:false};
    const response=await fetch(state.syncUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload),redirect:'follow'});
    if(!response.ok)throw Error('HTTP '+response.status);
    const result=await response.json();
    if(!result.ok)throw Error(result.error||'Google Sheets rejected the upload');
    if(Number(result.received)!==g.events.length)throw Error('Unexpected event confirmation from server');
    state.lastSyncAt=new Date().toISOString();await persist();
    $('notice').textContent='Saved game restored: '+result.received+' events sent for '+g.home.name+' vs '+g.away.name+'. Check Games, Events and Game_Attendance in Google Sheets.';
    alert('Google Sheets accepted '+result.received+' events for this game. Check the Events tab, then rebuild season statistics.');
  }catch(err){$('notice').textContent='Saved-game resync failed: '+err.message;alert('Resync failed: '+err.message)}
  finally{syncing=false;render()}
}
