function goalieStats(g,t){
 const ev=events(g), m=new Map();
 const ensure=n=>{n=String(n||'').trim();if(!n)return null;if(!m.has(n))m.set(n,{jersey:n,saves:0,ga:0});return m.get(n)};
 ensure(startingGoalie(g,t));
 for(const e of ev){if(e.type==='goalie_change'&&e.team===t)ensure(e.goalie);if(e.type==='save'&&e.team===t){const x=ensure(e.goalie);if(x)x.saves++}if(e.type==='goal'&&e.team!==t){const x=ensure(e.goalieAgainst);if(x)x.ga++}}
 return [...m.values()];
}
function buildLiveSummary(g){
 const ev=events(g), names=[g.home.name,g.away.name];
 const goals=ev.filter(e=>e.type==='goal'),pen=ev.filter(e=>e.type==='penalty');
 const score=goals.slice().sort((a,b)=>a.quarter-b.quarter||(a.elapsed??0)-(b.elapsed??0)).map(e=>`<div class="event">Q${e.quarter} · ${escapeHTML(e.remaining??'—')} · <b>${escapeHTML(names[e.team])}</b> #${escapeHTML(e.scorer)}${e.assist?' (A #'+escapeHTML(e.assist)+')':''}</div>`).join('')||'<small>No goals recorded.</small>';
 const penalties=pen.slice().sort((a,b)=>a.quarter-b.quarter||(a.elapsed??0)-(b.elapsed??0)).map(e=>`<div class="event">Q${e.quarter} · ${escapeHTML(e.remaining??'—')} · <b>${escapeHTML(names[e.team])}</b> #${escapeHTML(e.player)} · ${escapeHTML(e.infraction)} · ${Number(e.duration)||1} min</div>`).join('')||'<small>No penalties recorded.</small>';
 const goalie=[0,1].map(t=>goalieStats(g,t).map(x=>{const shots=x.saves+x.ga;return `<div class="event">${escapeHTML(names[t])} #${escapeHTML(x.jersey)} · ${x.saves} saves · ${x.ga} GA · ${shots} shots · ${shots?(100*x.saves/shots).toFixed(1)+'%':'—'} SV%</div>`}).join('')).join('')||'<small>No goalie statistics yet.</small>';
 return `<details><summary><b>Goals (${goals.length})</b></summary>${score}</details><details><summary><b>Penalties (${pen.length})</b></summary>${penalties}</details><details><summary><b>Goalies / Save percentage</b></summary>${goalie}</details><small>Save percentage uses saves ÷ (saves + recorded goals against). Goals with no assigned goalie are excluded.</small>`;
}
