function auditResults(g){const h=totals(g,0).goals,a=totals(g,1).goals;const issues=[];if(g.verifiedHome===null||g.verifiedHome===undefined||g.verifiedAway===null||g.verifiedAway===undefined)issues.push('Enter and save both verified scoreboard totals.');else if(h!==g.verifiedHome||a!==g.verifiedAway)issues.push(`Score mismatch: recorded ${h}–${a}, verified ${g.verifiedHome}–${g.verifiedAway}.`);for(const e of events(g)){if(e.quarter<1||e.quarter>4)issues.push('An event has an invalid quarter.');if(e.type!=='save'&&e.type!=='goalie_change'&&(!Number.isInteger(e.elapsed)||e.elapsed<0||e.elapsed>720))issues.push('An event has an invalid time.');if(e.type==='goal'&&!/^\d+$/.test(e.scorer||''))issues.push('A goal is missing a scorer number.');if(e.type==='save'&&!validJersey(String(e.goalie||'')))issues.push('A save has no assigned goalie.');if(e.type==='goalie_change'&&!validJersey(String(e.goalie||'')))issues.push('A goalie change has no goalie number.');if(e.type==='penalty'&&(!/^\d+$/.test(e.player||'')||!e.infraction))issues.push('A penalty is incomplete.')}return [...new Set(issues)]}
