$('reviewEvents').onclick=ev=>{const b=ev.target.closest('button[data-edit]');const g=active();if(!b||!g||g.status==='final')return;const e=g.events.find(e=>e.id===b.dataset.edit);if(!e)return;editingId=e.id;$('editTeam').value=String(e.team);$('editQuarter').value=String(e.quarter);$('editClock').classList.toggle('hidden',e.type==='save'||e.type==='goalie_change');$('editSave').classList.toggle('hidden',e.type!=='save'&&e.type!=='goalie_change');$('editGoalie').value=e.goalie||'';$('editGoal').classList.toggle('hidden',e.type!=='goal');$('editPenalty').classList.toggle('hidden',e.type!=='penalty');const [m,s]=(e.remaining||'').split(':');$('editMin').value=m===''?'':Number(m);$('editSec').value=(!s||s==='--')?'':Number(s);$('editScorer').value=e.scorer||'';$('editAssist').value=e.assist||'';$('editGoalType').value=e.goalType||'EV';$('editPlayer').value=e.player||'';$('editInfraction').value=e.infraction||'Other';$('editPenDuration').value=String(e.duration|| (e.infraction==='Dangerous Shot'?2:1));v19EditPads(e.type);$('editDialog').showModal()};
$('editTeam').onchange=()=>{const g=active(),e=g?.events.find(x=>x.id===editingId);if(!e)return;for(const id of ['editScorer','editAssist','editPlayer','editGoalie'])$(id).value='';v19EditPads(e.type)}; $('cancelEdit').onclick=()=>$('editDialog').close();$('editForm').onsubmit=async ev=>{ev.preventDefault();const g=active();if(!g||g.status==='final')return;const e=g.events.find(x=>x.id===editingId);if(!e)return;const et=Number($('editTeam').value);if(e.type==='goal'&&(!v19Require(g,et,$('editScorer').value.trim(),'Scorer')||!v19Require(g,et,$('editAssist').value.trim(),'Assist',true)))return;if(e.type==='penalty'&&!v19Require(g,et,$('editPlayer').value.trim(),'Penalized player'))return;if((e.type==='save'||e.type==='goalie_change')&&!v19Require(g,et,$('editGoalie').value.trim(),'Goalie'))return;const before=structuredClone(e),rawMin=$('editMin').value.trim(),rawSec=$('editSec').value.trim(),sec=rawSec===''?0:Number(rawSec),t=Number(rawMin)*60+sec;if(e.type!=='save'&&e.type!=='goalie_change'&&(rawMin===''||!Number.isInteger(Number(rawMin))||!Number.isInteger(sec)||t<0||t>720||sec>59||sec<0)){alert('Time must be between 12:00 and 00:00.');return}e.team=Number($('editTeam').value);e.quarter=Number($('editQuarter').value);if(e.type!=='save'&&e.type!=='goalie_change'){e.remaining=String(rawMin).padStart(2,'0')+':'+(rawSec===''?'--':String(sec).padStart(2,'0'));e.secondsKnown=rawSec!=='';e.elapsed=720-t;e.minute=Math.max(1,Math.ceil(e.elapsed/60))}if(e.type==='save'||e.type==='goalie_change'){e.goalie=$('editGoalie').value.trim();if(!validJersey(e.goalie)){alert('Enter the goalie jersey number.');return}}if(e.type==='goal'){e.scorer=$('editScorer').value.trim();e.assist=$('editAssist').value.trim();e.goalType=$('editGoalType').value;e.goalieAgainst=currentGoalie(g,1-e.team);if(!/^\d+$/.test(e.scorer)||e.assist&&!/^\d+$/.test(e.assist)){alert('Use jersey numbers only.');return}}if(e.type==='penalty'){e.player=$('editPlayer').value.trim();e.infraction=$('editInfraction').value;e.duration=Number($('editPenDuration').value);if(!/^\d+$/.test(e.player)){alert('Enter the penalized player number.');return}}enrichEvent(g,e);e.version=(e.version||0)+1;e.dirty=true;auditLog(g,'edit_event',before,structuredClone(e));$('editDialog').close();await commit();renderReview()};

