// Opening-clock changes before any recorded play replace the initial goalie for attendance purposes.
function attendanceParticipation(g,t,pid,confirmedOpening=new Set()){
 const ev=events(g);let opening=playerId(g,t,startingGoalie(g,t));let playSeen=false;
 for(const e of ev){
  const openingChange=e.type==='goalie_change'&&Number(e.quarter)===1&&((e.elapsed!==null&&e.elapsed!==undefined&&e.elapsed!==''&&Number(e.elapsed)===0)||confirmedOpening.has(e.id))&&!playSeen;
  if(openingChange){if(Number(e.team)===t){const next=e.goalieId||playerId(g,t,e.goalie);if(next)opening=next;}continue;}
  playSeen=true;
  if([e.scorerId,e.assistId,e.playerId,e.goalieId,e.goalieAgainstId].includes(pid))return true;
  // Legacy events may lack IDs; resolve against the historical roster.
  const et=Number(e.team);
  if(e.type==='goal'&&[playerId(g,et,e.scorer),playerId(g,et,e.assist),playerId(g,1-et,e.goalieAgainst)].includes(pid))return true;
  if(e.type==='penalty'&&playerId(g,et,e.player)===pid)return true;
  if((e.type==='save'||e.type==='goalie_change')&&playerId(g,et,e.goalie)===pid)return true;
 }
 return opening===pid;
}
// V21.2: correct existing attendance without touching events or game status.
$('gameHistory').addEventListener('click',ev=>{
 const b=ev.target.closest('button[data-attendance-edit]');if(!b)return;
 const g=state.games.find(x=>x.id===b.dataset.attendanceEdit);if(!g)return;
 const dialog=$('historyAttendanceDialog');
 $('historyAttendanceTitle').textContent=g.home.name+' vs '+g.away.name+' · '+g.date;
 const confirmedOpening=new Set();
 for(const e of events(g)){if(e.type!=='goalie_change'||Number(e.quarter)!==1)break; if(e.elapsed==null||e.elapsed===''){if(confirm('Was the untimed opening goalie change for '+(Number(e.team)?g.away:g.home).name+' to #'+e.goalie+' made before any game time elapsed? Select Cancel if the original goalie played.'))confirmedOpening.add(e.id);else break;}else if(Number(e.elapsed)!==0)break;}
 $('historyAttendanceRows').innerHTML=[0,1].map(t=>{
 const id=teamId(g,t),a=g.attendance?.[id]||{},rs=roster(g,t);
 return '<h3>'+escapeHTML((t?g.away:g.home).name)+'</h3>'+Object.entries(a).map(([pid,playing])=>{
 const r=rs.find(x=>x.id===pid);const used=attendanceParticipation(g,t,pid,confirmedOpening);
 return '<label style="display:flex;gap:8px;align-items:center"><input style="width:24px;min-height:24px" type="checkbox" data-team="'+escapeHTML(id)+'" data-player="'+escapeHTML(pid)+'" '+(playing?'checked':'')+' '+(used?'disabled':'')+'>'+escapeHTML(r?'#'+r.jersey+' '+r.name:pid)+(used?' (recorded participation)':'')+'</label>';
 }).join('');}).join('');
 $('historyAttendanceSave').onclick=async()=>{
 if(syncing){alert('Wait for the current sync to finish.');return;}
 const changes=[...$('historyAttendanceRows').querySelectorAll('input:not(:disabled)')].filter(x=>g.attendance[x.dataset.team][x.dataset.player]!==x.checked).map(x=>({teamId:x.dataset.team,playerId:x.dataset.player,playing:x.checked}));
 if(!changes.length){dialog.close();return;}
 if(!navigator.onLine||!state.syncUrl||!state.syncKey){alert('Connect to Google Sheets before saving historical corrections.');return;}
 if(!confirm('Save '+changes.length+' attendance correction(s) to Google Sheets and this device? Events and scores will not change.'))return;
 syncing=true;$('historyAttendanceSave').disabled=true;
 try{const response=await fetch(state.syncUrl,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({key:state.syncKey,action:'correctAttendance',gameId:g.id,changes}),redirect:'follow'});if(!response.ok)throw Error('HTTP '+response.status);const result=await response.json();if(!result.ok||result.corrected!==changes.length)throw Error(result.error||'Unexpected confirmation');for(const c of changes)g.attendance[c.teamId][c.playerId]=c.playing;await persist();dialog.close();render();alert('Attendance corrected on Google Sheets and this device.');}catch(e){alert('Correction not fully confirmed: '+e.message+'. Check Google Sheets before retrying.');}finally{syncing=false;$('historyAttendanceSave').disabled=false;}
 };
 dialog.showModal();
});
