async function v214Add(prefix,pre){
 const g=pre?pregameGame():active();if(!g||g.status==='final')return;
 const t=Number($(prefix+'Team').value),id=teamId(g,t),jersey=$(prefix+'Jersey').value.trim(),mode=$(prefix+'Mode').value;
 let name=$(prefix+'Name').value.trim(),goalie=$(prefix+'Goalie').checked,source=null;
 if(mode==='borrow'){source=Object.values(state.rosters).flat().find(r=>r.id===$(prefix+'Borrow').value);if(!source||source.teamId===id){alert('Choose a player from another team.');return}name=source.name;}
 if(!validJersey(jersey)||!name){alert('Enter jersey and player name.');return}
 const rs=roster(g,t);if(rs.some(r=>Number(r.jersey)===Number(jersey)||r.name.toLowerCase()===name.toLowerCase())||source&&[0,1].some(k=>roster(g,k).some(r=>r.id===source.id))){alert('Duplicate jersey, name or player already assigned to this game.');return}
 const player={id:source?source.id:uuid(),teamId:id,jersey,name,goalie,dirty:mode==='permanent',version:1,assignment:mode,originalTeam:source?.teamId||id};
 if(!g.rosterSnapshot)g.rosterSnapshot=Object.fromEntries([0,1].map(k=>[teamId(g,k),structuredClone(roster(g,k))]));
 gameAttendance(g,t)[player.id]=true;g.rosterSnapshot[id].push(player);
 if(mode==='permanent')(state.rosters[id]||(state.rosters[id]=[])).push({...player});
 if(pre){pregameDraft().rosterSnapshot=g.rosterSnapshot;pregameDraft().reviewed=false;await persist();renderPregameRosters();}else{g.version=(g.version||0)+1;g.metaDirty=true;await commit();renderRosters();}
 $(prefix+'Name').value='';$(prefix+'Jersey').value='';v214Options(prefix);
}
function v214Options(prefix){const pre=prefix==='pregameAddPlayer',g=pre?pregameGame():active();if(!g)return;const id=teamId(g,Number($(prefix+'Team').value));const borrow=$(prefix+'Mode').value==='borrow';const sel=$(prefix+'Borrow');sel.innerHTML='<option value="">Choose league player</option>'+Object.values(state.rosters||{}).flat().filter(r=>r.teamId!==id).map(r=>'<option value="'+escapeHTML(r.id)+'">'+escapeHTML(r.teamId+' · #'+r.jersey+' '+r.name)+'</option>').join('');sel.hidden=!borrow;$(prefix+'Name').required=!borrow;$(prefix+'Name').hidden=borrow;}
for(const prefix of ['pregameAddPlayer','addPlayer']){for(const suffix of ['Mode','Team'])$(prefix+suffix).addEventListener('change',()=>v214Options(prefix));$(prefix+'Borrow').addEventListener('change',()=>{const r=Object.values(state.rosters||{}).flat().find(r=>r.id===$(prefix+'Borrow').value);if(r){$(prefix+'Jersey').value=r.jersey;$(prefix+'Goalie').checked=!!r.goalie;}});}
